"""REL-12: exercise the read-only progress CLI using stdlib fixtures."""
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "scripts"))
import progress_report as pr

SCRIPT = Path(pr.__file__).resolve()
TODAY = "2026-10-24"


class ProgressCheck(unittest.TestCase):
    def test_check_validates_both_outputs_without_writing(self):
        # Freeze the acceptance matrix before implementation. Each case gets
        # an independent source tree and outputs generated by the existing CLI.
        for custom in (False, True):
            for state in ("current", "json-stale", "html-stale", "date-stale",
                          "json-missing", "html-missing", "both-missing",
                          "json-invalid", "html-invalid"):
                with self.subTest(custom=custom, state=state), tempfile.TemporaryDirectory() as tmp:
                    base = Path(tmp)
                    root = base / "source"
                    for directory in ("lessons", "learning-records", "assets"):
                        (root / directory).mkdir(parents=True)
                    (root / "lessons/0001-example.html").write_text("lesson", encoding="utf-8")
                    (root / "learning-records/0001-lesson-001-complete.md").write_text("done", encoding="utf-8")
                    (root / "assets/paper-deck.js").write_text(
                        'window.PAPER_DECK = [{id:"card",lesson:1}];', encoding="utf-8")
                    j = base / "custom.json" if custom else root / "assets/progress-data.json"
                    h = base / "custom.html" if custom else root / "progress.html"
                    args = [sys.executable, "-B", str(SCRIPT), "--root", str(root), "--today", TODAY]
                    if custom:
                        args += ["--json-out", str(j), "--html-out", str(h)]
                        # Default paths must be ignored when overrides are supplied.
                        (root / "assets/progress-data.json").write_text("sentinel", encoding="utf-8")
                        (root / "progress.html").write_text("sentinel", encoding="utf-8")
                    generated = subprocess.run(args, capture_output=True, text=True, cwd=base)
                    self.assertEqual(generated.returncode, 0, generated.stderr)
                    self.assertEqual(j.read_text(encoding="utf-8"), pr.dumps(pr.build_report(root, TODAY)))
                    self.assertEqual(h.read_text(encoding="utf-8"), pr.render_html(pr.build_report(root, TODAY)))
                    affected = []
                    if state == "date-stale":
                        args[args.index(TODAY)] = "2026-10-25"
                        affected = [j, h]
                    elif state.startswith("json-"):
                        affected = [j]
                    elif state.startswith("html-"):
                        affected = [h]
                    elif state == "both-missing":
                        affected = [j, h]
                    for path in affected:
                        if state.endswith("missing"):
                            path.unlink()
                        elif state.endswith("invalid"):
                            path.write_bytes(b"\xff")
                        elif state != "date-stale":
                            path.write_text("{}" if path == j else "<html>stale</html>", encoding="utf-8")
                    before = {str(p.relative_to(base)): (p.read_bytes() if p.is_file() else None,
                              p.stat().st_mtime_ns, p.stat().st_mode)
                              for p in [base, *base.rglob("*")]}
                    checked = subprocess.run(args + ["--check"], capture_output=True, text=True, cwd=base,
                                             env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})
                    after = {str(p.relative_to(base)): (p.read_bytes() if p.is_file() else None,
                             p.stat().st_mtime_ns, p.stat().st_mode)
                             for p in [base, *base.rglob("*")]}
                    self.assertEqual(after, before, "--check wrote to the source/output tree")
                    if state == "current":
                        self.assertEqual(checked.returncode, 0, checked.stderr)
                    else:
                        self.assertNotEqual(checked.returncode, 0)
                        diagnostic = checked.stdout + checked.stderr
                        for path in affected:
                            self.assertIn(str(path), diagnostic)
                        self.assertNotIn("Traceback", diagnostic)


if __name__ == "__main__":
    unittest.main()
